                        selected = item
                if selected is None:
                    break
                _, txn, pos = selected
                partial.insert(pos, txn)
                remaining.remove(txn)
            partial.extend(remaining)
            return partial

        preference = [[0] * n for _ in range(n)]
        for left in range(n):
            if time.perf_counter() >= construct_deadline:
                break
            for right in range(left + 1, n):
                if time.perf_counter() >= construct_deadline:
                    break
                forward = cost([left, right])
                backward = cost([right, left])
                if forward <= backward:
                    preference[right][left] = backward - forward
                else:
                    preference[left][right] = forward - backward

        strength = []
        for txn in range(n):
            outgoing = sum(preference[txn])
            incoming = sum(preference[other][txn] for other in range(n))
            strength.append((outgoing - incoming, txn))
        insertion_order = [
            txn for _, txn in sorted(strength, key=lambda x: (-x[0], x[1]))
        ]

        order = []
        for txn in insertion_order:
            best = None
            for pos in range(len(order) + 1):
                trial = order[:pos] + [txn] + order[pos:]
                penalty = 0
                for i in range(len(trial)):
                    for j in range(i + 1, len(trial)):
                        penalty += preference[trial[i]][trial[j]]
                item = (penalty, pos, trial)
                if best is None or item[:2] < best[:2]:
                    best = item
            order = best[2]

        for txn in order[:]:
            if time.perf_counter() >= construct_deadline:
                break
            partial = [x for x in order if x != txn]
            best = None
            for pos in range(len(partial) + 1):
                trial = partial[:pos] + [txn] + partial[pos:]
                item = (cost(trial), pos, trial)
                if best is None or item[:2] < best[:2]:
                    best = item
            order = best[2]

        improved = True
        while improved and time.perf_counter() < construct_deadline:
            improved = False
            current = cost(order)
            for index, txn in enumerate(order):
                if time.perf_counter() >= construct_deadline:
                    break
                partial = order[:index] + order[index + 1:]
                best_value = current
                best_order = order
                for pos in range(len(partial) + 1):
                    if pos == index:
                        continue
                    trial = partial[:pos] + [txn] + partial[pos:]
                    value = cost(trial)
                    if value < best_value:
                        best_value, best_order = value, trial
                if best_value < current:
                    order = best_order
                    improved = True
                    break
        return order

    for reverse in (False, True):
        if time.perf_counter() >= construct_deadline:
            break
        candidate = construct(reverse)
        candidate_cost = cost(candidate)
        if candidate_cost < best_cost:
            best_seq, best_cost = candidate, candidate_cost

    ruin_count = min(8, max(3, n // 8), n)

    for attempt in range(4):
        if time.perf_counter() >= deadline:
            break

        impacts = []
        for txn in best_seq:
            if time.perf_counter() >= deadline:
                break
            remainder = [x for x in best_seq if x != txn]
            impacts.append((best_cost - cost(remainder), txn))
        if len(impacts) != n:
            break

        impacts.sort(key=lambda x: (-x[0], (x[1] - attempt) % max(1, n)))
        removed = {txn for _, txn in impacts[:ruin_count]}
        partial = [txn for txn in best_seq if txn not in removed]

        while removed and time.perf_counter() < deadline:
            choice = None
            for txn in sorted(removed, key=lambda x: (x - attempt) % max(1, n)):
                for pos in range(len(partial) + 1):
                    trial = partial[:pos] + [txn] + partial[pos:]
                    item = (cost(trial), txn, pos, trial)
                    if choice is None or item[:3] < choice[:3]:
                        choice = item
            if choice is None:
                break
            _, txn, _, partial = choice
            removed.remove(txn)

        partial.extend(sorted(removed))
        candidate = partial
        candidate_cost = cost(candidate)

        # The old final phase only explored adjacent swaps.  Relocation includes
        # that neighborhood and can repair a transaction misplaced by many slots.
        accepted_moves = 0
        while accepted_moves < 2 and time.perf_counter() < deadline:
            found = False
            for index, txn in enumerate(candidate):
                if time.perf_counter() >= deadline:
                    break
                remainder = candidate[:index] + candidate[index + 1:]
                for pos in range(len(remainder) + 1):
                    if pos == index:
                        continue
                    trial = remainder[:pos] + [txn] + remainder[pos:]
                    value = cost(trial)
                    if value < candidate_cost:
                        candidate, candidate_cost = trial, value
                        accepted_moves += 1
                        found = True
                        break
                if found:
                    break
            if not found:
                break

        if candidate_cost < best_cost:
            best_seq, best_cost = candidate[:], candidate_cost

    if len(best_seq) != n or set(best_seq) != set(range(n)):
        best_seq = identity
        best_cost = cost(identity)

    return best_cost, best_seq

